test("every built issue contains PUBLICATION_DECLARATION and required deliberate bypass statements", () => {
  const [qaFinding] = parseFixture("voicebox-qa-station-delta.md", "qa-station").findings;
  const [perfFinding] = parseFixture("voicebox-perf-review-delta.md", "perf-review").findings;
  const [secretFinding] = parseFixture("voicebox-secret-scan-delta.md", "secret-scan").findings;

  for (const finding of [qaFinding, perfFinding, secretFinding]) {
    const verdict = routeFinding(finding);
    const issue = buildIssue(finding, verdict, { repo: "owner/voicebox" });

    assert.ok(issue.body.includes(PUBLICATION_DECLARATION), "missing PUBLICATION_DECLARATION in issue body");
    assert.match(
      issue.body,
      /bypasses the factory's\s+public sinks on purpose/,
      "issue body must state deliberate bypass of public sinks",
    );
    assert.match(
      issue.body,
      /embargo/,
      "issue body must reference the factory embargo",
    );
    assert.match(
      issue.body,
      /No bead was created from the scan/,
      "issue body must state no bead was created from the scan",
    );
  }
});

