test("board I/O helpers parse tool outputs and fail safely on errors", () => {
  const fp = "1".repeat(64);

  // existingIssues
  const issuesMock = {
    status: 0,
    stdout: JSON.stringify([{ number: 1, state: "open", body: `<!-- factory-fingerprint: ${fp} -->` }]),
  };
  const issueMap = existingIssues("owner/repo", { run: () => issuesMock });
  assert.ok(issueMap.has(fp));
  assert.deepEqual(issueMap.get(fp), [{ number: "1", state: "open" }]);

  // existingIssues failure cases
  assert.equal(existingIssues("owner/repo", { run: () => ({ status: 1, error: new Error("fail") }) }), null);
  assert.equal(existingIssues("owner/repo", { run: () => ({ status: 0, stdout: "invalid-json" }) }), null);

  // knownLabels
  const labelsMock = { status: 0, stdout: JSON.stringify([{ name: "bug" }, { name: "enhancement" }]) };
  assert.deepEqual(knownLabels("owner/repo", { run: () => labelsMock }), ["bug", "enhancement"]);
  assert.equal(knownLabels("owner/repo", { run: () => ({ status: 1 }) }), null);

  // readIssue
  const issueViewMock = { status: 0, stdout: JSON.stringify({ number: 42, title: "issue 42" }) };
  assert.deepEqual(readIssue(42, "owner/repo", { run: () => issueViewMock }), { number: 42, title: "issue 42" });
  assert.equal(readIssue(42, "owner/repo", { run: () => ({ status: 1 }) }), null);

  // existingBeadFingerprints from externalRef and description
  const beadsMock = {
    status: 0,
    stdout: JSON.stringify([
      { id: "vb-1", status: "open", external_ref: `factory:${fp}` },
      { id: "vb-2", status: "closed", description: `Some details\nFingerprint: ${"2".repeat(64)}` },
    ]),
  };
  const beadMap = existingBeadFingerprints("/tmp/target", { run: () => beadsMock });
  assert.ok(beadMap.has(fp));
  assert.ok(beadMap.has("2".repeat(64)));
  assert.equal(existingBeadFingerprints("/tmp/target", { run: () => ({ status: 1 }) }), null);
});

