test("plan output is sanitised too: a CI log must never capture the raw finding title", () => {
  // The plan is printed to stdout, and in CI stdout is a log that cannot be un-published. The raw
  // title used to be printed here, which disclosed a credential the triage model had echoed into it.
  const canary = `sk-${"Q".repeat(24)}`;
  const home = homedir();
  const rewritten = fixture("voicebox-qa-station-delta.md").replace(
    "Folder chip assertion waits on a load-sensitive timeout",
    `Password leak ${canary} in ${home}/worktrees/private/secret.txt`,
  );
  const res = runCli({
    args: ["--report", "voicebox-qa-station-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-qa-station-delta.md": rewritten },
  });
  try {
    assert.equal(res.status, 0, res.stderr);
    assert.ok(!res.stdout.includes(canary), `the plan captured the raw credential: ${res.stdout}`);
    assert.ok(!res.stdout.includes(home), `the plan captured a home path: ${res.stdout}`);
    assert.match(res.stdout, /\[redacted:openai-key\]/, "the plan must show the masked form where the value was");
  } finally {
    rmSync(res.box, { recursive: true, force: true });
  }
});

