test("CLI exits with code 1 on missing arguments or conflicting flags", () => {
  // Neither --report nor --report-dir
  const noReport = runCli({ args: ["--repo", "owner/voicebox"] });
  try {
    assert.equal(noReport.status, 1);
    assert.match(noReport.stderr, /one of --report or --report-dir is required/);
  } finally {
    rmSync(noReport.box, { recursive: true, force: true });
  }

  // Both --report and --report-dir
  const both = runCli({ args: ["--report", "a.md", "--report-dir", "dir", "--repo", "owner/voicebox"] });
  try {
    assert.equal(both.status, 1);
    assert.match(both.stderr, /--report and --report-dir are mutually exclusive/);
  } finally {
    rmSync(both.box, { recursive: true, force: true });
  }

  // Missing repo: PLAN mode is local and needs none; the modes that WRITE to a tracker refuse.
  const noRepo = runCli({
    args: ["--report", "voicebox-qa-station-delta.md"],
    reports: { "voicebox-qa-station-delta.md": fixture("voicebox-qa-station-delta.md") },
    env: { VOICEBOX_FACTORY_REPO: null },
  });
  try {
    assert.equal(noRepo.status, 0, `a local plan needs no repository: ${noRepo.stderr}`);
    assert.match(noRepo.stdout, /PUBLISH ISSUE/);
    assert.equal(noRepo.ghCalls.length, 0, "a local plan contacted gh");
  } finally {
    rmSync(noRepo.box, { recursive: true, force: true });
  }

  for (const [flag, value] of [["--file-issues", null], ["--review", "7"], ["--promote", "7"]]) {
    const res = runCli({
      args: ["--report", "voicebox-qa-station-delta.md", flag, ...(value ? [value] : []), ...(flag === "--review" ? ["--reviewed-by", "alice"] : [])],
      reports: { "voicebox-qa-station-delta.md": fixture("voicebox-qa-station-delta.md") },
      env: { VOICEBOX_FACTORY_REPO: null },
    });
    try {
      assert.equal(res.status, 1, `${flag} without --repo must refuse: ${res.stdout}${res.stderr}`);
      assert.match(res.stderr, /is required by --(file-issues|review|promote)/);
    } finally {
      rmSync(res.box, { recursive: true, force: true });
    }
  }

  // Unreadable report file
  const unreadable = runCli({
    args: ["--report", "nonexistent-delta.md", "--repo", "owner/voicebox"],
  });
  try {
    assert.equal(unreadable.status, 1);
    assert.match(unreadable.stderr, /not a readable file/);
  } finally {
    rmSync(unreadable.box, { recursive: true, force: true });
  }

  // Empty report-dir
  const emptyDir = runCli({
    args: ["--report-dir", "%PRIVATE%", "--repo", "owner/voicebox"],
    reports: {},
  });
  try {
    assert.equal(emptyDir.status, 2);
    assert.match(emptyDir.stderr, /no \*-delta\.md reports/);
  } finally {
    rmSync(emptyDir.box, { recursive: true, force: true });
  }
});

