test("A SEEDED HIGH CANNOT DISAPPEAR: the factory's public sink withholds it, this publisher must not", () => {
  // The exact failure this guards. The factory's own public sinks embargo high/critical findings
  // (mirrored in EMBARGOED_SEVERITIES from lib/embargo.py), so a HIGH routed through them vanishes
  // from the tracker: no issue, no bead, no reader. This publisher deliberately bypasses that embargo,
  // declared on every issue. If anyone ever restores the withholding here — including by delegating
  // to the factory's sink decision — this test goes red. The mutation that proves it is documented in
  // docs/27 section 11: make routeFinding return `skip` for EMBARGOED_SEVERITIES and five tests fail.
  const seeded = {
    agent: "perf-review", ruleId: "blocking-boot-probe", path: "server.mjs", lineNumber: "210",
    title: "Startup probe blocks the boot banner", description: "d", snippet: "await probeAll()",
    remediation: "r", state: "new", effectiveSeverity: "high", severityReported: "high",
    identityCritical: false, fingerprint: "7".repeat(64), identitySource: "recomputed-and-verified",
  };

  // (a) The counterfactual, stated so it cannot be forgotten: the factory's sink WOULD withhold it.
  assert.ok(EMBARGOED_SEVERITIES.has("high"), "the mirrored embargo set must still contain the high band");
  const factoryPublicSinkWouldWithhold = EMBARGOED_SEVERITIES.has(seeded.effectiveSeverity);
  assert.equal(factoryPublicSinkWouldWithhold, true, "the factory's public sink withholds this band");

  // (b) This publisher publishes it anyway, with the bypass stated on the issue.
  const verdict = routeFinding(seeded);
  assert.equal(verdict.action, "issue", "a seeded HIGH must be published, not withheld");
  const issue = buildIssue(seeded, verdict, { privateRoot: "/tmp/p", repo: "owner/voicebox" });
  assert.ok(issue.body.includes(PUBLICATION_DECLARATION), "the bypass must be declared on the issue");
  assert.ok(issue.body.includes("factory-fingerprint"), "the published issue must carry the identity");
  assert.ok(!issue.body.includes("embargoed") || issue.body.includes("bypasses"), "the issue must not read as withheld");

  // (c) And through the real CLI, not only the unit path: the HIGH fixture plans an ISSUE.
  const res = runCli({
    args: ["--report", "voicebox-perf-review-delta.md", "--repo", "owner/voicebox", "--json"],
    reports: { "voicebox-perf-review-delta.md": fixture("voicebox-perf-review-delta.md") },
  });
  const critical = runCli({
    args: ["--report", "voicebox-secret-scan-delta.md", "--repo", "owner/voicebox", "--json"],
    reports: { "voicebox-secret-scan-delta.md": fixture("voicebox-secret-scan-delta.md") },
  });
  try {
    const highEntry = JSON.parse(res.stdout)[0];
    assert.equal(highEntry.action, "issue", `the seeded HIGH disappeared: ${res.stdout}`);
    assert.equal(highEntry.finding.severity, "high");
    assert.ok(highEntry.issue, "a published HIGH must carry its issue body");
    const criticalEntry = JSON.parse(critical.stdout)[0];
    assert.equal(criticalEntry.action, "issue", `the seeded CRITICAL disappeared: ${critical.stdout}`);
    assert.equal(criticalEntry.finding.severity, "critical");
    assert.ok(EMBARGOED_SEVERITIES.has("critical"));
  } finally {
    rmSync(res.box, { recursive: true, force: true });
    rmSync(critical.box, { recursive: true, force: true });
  }
});

test("CROSS-TARGET: the refusal cannot be walked around by a trailing slash or a missing header (round 3 P1)", () => {
  // Both were REAL bypasses: `.split("/").pop()` on "/repos/other/" is "", and the old guard only
  // refused when the parsed target was non-empty, so the comparison was skipped. A report whose
  // target cannot be read is not evidence that its findings belong in --repo.
  const base = fixture("voicebox-qa-station-delta.md");
  const cases = {
    "other-qa-station-delta.md": base.replace(/^# Software Factory Delta Report:.*$/m, "# Software Factory Delta Report: /repos/other/"),
    "notarget-qa-station-delta.md": base.replace(/^# Software Factory Delta Report:.*$/m, "# Software Factory Delta Report"),
    "empty-qa-station-delta.md": base.replace(/^# Software Factory Delta Report:.*$/m, "# Software Factory Delta Report: "),
    "backslash-qa-station-delta.md": base.replace(/^# Software Factory Delta Report:.*$/m, "# Software Factory Delta Report: repos\\other\\"),
  };
  for (const [name, text] of Object.entries(cases)) {
    const res = runCli({ args: ["--report", name, "--repo", "owner/voicebox"], reports: { [name]: text } });
    try {
      assert.equal(res.status, 1, `${name} was NOT refused: ${res.stdout}`);
      assert.match(res.stderr, /refusing to publish another repository's finding here/);
      assert.ok(!res.ghCalls.some((c) => c.startsWith("issue create")), `${name}: a foreign report planned a publication`);
    } finally {
      rmSync(res.box, { recursive: true, force: true });
    }
  }
  // OUR OWN repository with a trailing slash must be ALLOWED: without stripping the trailing
  // slash the parsed target is empty, and the fail-closed rule would then refuse a legitimate report.
  const ownSlash = runCli({
    args: ["--report", "voicebox-qa-station-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-qa-station-delta.md": base.replace(/^# Software Factory Delta Report:.*$/m, "# Software Factory Delta Report: /repos/voicebox/") },
  });
  try {
    assert.equal(ownSlash.status, 0, `our own target with a trailing slash was refused: ${ownSlash.stderr}`);
    assert.match(ownSlash.stdout, /PUBLISH ISSUE/);
  } finally {
    rmSync(ownSlash.box, { recursive: true, force: true });
  }

  // A case difference is the same repository, not a foreign one.
  const cased = runCli({
    args: ["--report", "VOICEBOX-qa-station-delta.md", "--repo", "owner/voicebox"],
    reports: { "VOICEBOX-qa-station-delta.md": base },
  });
  try {
    assert.equal(cased.status, 0, `a case difference was treated as foreign: ${cased.stderr}`);
  } finally {
    rmSync(cased.box, { recursive: true, force: true });
  }
});

test("HUMAN-REVIEW REASON: the flag carries WHY it was set, and the prose follows it (round 3 P2)", () => {
  const vuln = {
    agent: "vuln-discovery", ruleId: "unsanitized-html", path: "public/x.js", lineNumber: "1",
    title: "t", description: "d", snippet: "s", remediation: "r", state: "new",
    effectiveSeverity: "critical", severityReported: "critical", identityCritical: true,
    fingerprint: "4".repeat(64), identitySource: "recomputed-and-verified",
  };
  const verdict = routeFinding(vuln);
  assert.equal(verdict.humanReviewReason, "model-prose");
  const issue = buildIssue(vuln, verdict, { privateRoot: "/tmp/p", repo: "owner/voicebox" });
  assert.ok(issue.body.includes("<!-- factory-human-review-reason: model-prose -->"), "the reason must be on the issue");
  assert.match(issue.body, /model-authored and security-sensitive/);
  // The false claim the reviewer found: a security station's body used to say it changes functionality.
  assert.ok(
    !/This remediation changes functionality, so a human decides/.test(issue.body),
    "the body asserted a functionality change that was never established",
  );
  // ...and the round-5 correction: a security-only finding is marked for VERIFICATION, and the issue
  // must not promise that the bead will be BLOCKED, because by criterion it will not be.
  assert.match(issue.body, /Needs verification; not a blocker/, "a security-only issue did not carry the verification marker");
  assert.match(issue.body, /marked for verification|stays claimable/, "the issue did not say the bead stays claimable");
  assert.ok(!/filed BLOCKED/.test(issue.body), `a security-only issue promised a BLOCKED bead: ${issue.body}`);
  // A functionality change DOES say so, and does promise the block.
  const changing = routeFinding(vuln, { confirmedFunctionalityChange: true });
  assert.equal(changing.humanReviewReason, "both");
  const changingIssue = buildIssue(vuln, changing, { repo: "owner/voicebox", privateRoot: "/tmp/private" });
  assert.match(changingIssue.body, /Human review required before any implementation/);
  assert.match(changingIssue.body, /filed BLOCKED/);
  // The BOTH case is what makes the reason prose load-bearing: a hardcoded "changes functionality"
  // sentence reads identically for the functionality-only row, so only this assertion notices that the
  // security half was dropped.
  assert.match(changingIssue.body, /changes functionality AND this station's prose is model-authored/);
  assert.match(changingIssue.body, /<!-- factory-human-review-reason: both -->/);

  // A functionality change carries its own reason, and both are named when both hold.
  const quality = { ...vuln, agent: "qa-station", identityCritical: false, effectiveSeverity: "high", ruleId: "flake-instrumentation" };
  assert.equal(routeFinding(quality).humanReviewReason, null);
  assert.equal(routeFinding(quality, { confirmedFunctionalityChange: true }).humanReviewReason, "functionality-change");
  assert.equal(routeFinding(vuln, { confirmedFunctionalityChange: true }).humanReviewReason, "both");
  assert.match(humanReviewWhy("both"), /changes functionality AND/);

  // The BEAD states the true reason, and falls back to inference for an older issue. The security
  // rows must remain CLAIMABLE (Paul's criterion is functionality, not station class); the
  // functionality row must block.
  for (const [marker, expected, blocks] of [
    ["<!-- factory-human-review-reason: model-prose -->", /model-authored and security-sensitive/, false],
    ["", /model-authored and security-sensitive/, false], // no reason marker + a security station => inferred
    ["<!-- factory-human-review-reason: functionality-change -->", /changes functionality/, true],
  ]) {
    const res = runCli({
      args: ["--promote", "10", "--apply", "--repo", "owner/voicebox"],
      stubGh: ghStubViewing(
        JSON.stringify({
          number: 10, state: "OPEN", title: "[human-review] [factory/critical] vuln-discovery: stub", url: "https://example.invalid/10", labels: [],
          body: `<!-- factory-fingerprint: ${"5".repeat(64)} -->\n<!-- factory-station: vuln-discovery -->\n<!-- factory-severity: critical -->\n<!-- factory-state: new -->\n<!-- factory-human-review -->\n${marker}`,
          comments: [{ body: "<!-- factory-review: alice -->" }],
        }),
      ),
    });
    try {
      assert.equal(res.status, 0, res.stderr);
      const blocked = res.bdCalls.filter((c) => c.startsWith("update") && c.includes("--status blocked"));
      const comment = res.bdCalls.find((c) => c.startsWith("comment"));
      if (!blocks) {
        // Security-only: the issue is marked for verification, the BEAD is claimable (Paul's
        // BLOCKED criterion is a major functionality change, not a station class).
        assert.deepEqual(blocked, [], `a security-only promotion blocked the bead: ${res.bdCalls.join(" | ")}`);
        assert.equal(comment, undefined, `a security-only promotion posted a blocked comment: ${comment}`);
        const create = res.bdCalls.find((c) => c.startsWith("create"));
        assert.match(create, /Needs verification/, `the bead did not say it needs verification: ${create}`);
        assert.match(create, /claimable/, `the bead did not say it is claimable: ${create}`);
        // The reason still reaches the bead, from the marker or from the station inference.
        assert.match(create, expected, `the bead did not carry the real reason: ${create}`);
        // The false claim round 3 caught: a security station must never assert a functionality change.
        assert.ok(
          !/this remediation changes functionality|the bead is BLOCKED/.test(create),
          `a security-only bead asserted a cause or a block that was never established: ${create}`,
        );
      } else {
        assert.equal(blocked.length, 1, `a functionality-changing promotion did not block: ${res.bdCalls.join(" | ")}`);
        assert.ok(comment, `no bead comment: ${res.bdCalls.join(" | ")}`);
        assert.match(comment, expected, `the bead comment did not state the real reason: ${comment}`);
      }
    } finally {
      rmSync(res.box, { recursive: true, force: true });
    }
  }
});

test("REMOVED SEAM: --comment and --issue-number are refused by name, not silently accepted", () => {
  // Coord's ruling: the existing-issue comment surface belongs to miniapps' commenter. A stale caller
  // must be told that, rather than discovering it from a usage dump or a silent no-op.
  for (const flag of ["--comment", "--issue-number"]) {
    const res = runCli({
      args: ["--report", "voicebox-qa-station-delta.md", flag, "42", "--repo", "owner/voicebox"],
      reports: { "voicebox-qa-station-delta.md": fixture("voicebox-qa-station-delta.md") },
    });
    try {
      assert.equal(res.status, 1, `${flag} was accepted: ${res.stdout}`);
      assert.match(res.stderr, /was removed: this publisher does not comment on existing issues/);
      assert.match(res.stderr, /factory-issue-commenter\.mjs/);
      assert.equal(res.ghCalls.length, 0, `${flag} reached gh`);
    } finally {
      rmSync(res.box, { recursive: true, force: true });
    }
  }
  // The usage text must not advertise the removed mode either.
  const help = runCli({ args: ["--help"] });
  try {
    assert.ok(!/--comment/.test(help.stdout) && !/--issue-number/.test(help.stdout), "the usage still lists the removed mode");
    assert.match(help.stdout, /--finding <fingerprint>/);
  } finally {
    rmSync(help.box, { recursive: true, force: true });
  }
});

test("READ-ONLY INBOUND PROMOTION: a reviewed human issue with triage markers can be promoted", () => {
  // Coord: promotion of a reviewed inbound human issue IS allowed after triage+review, never before.
  const fp = "b1".repeat(32);
  const triageComment = [
    "Scanned by the factory.",
    `<!-- factory-triage-comment: ${fp} -->`,
    "<!-- factory-station: qa-station -->",
    "<!-- factory-severity: high -->",
    "<!-- factory-state: new -->",
  ].join("\n");
  const inbound = (reviewed) =>
    JSON.stringify({
      number: 42, state: "OPEN", title: "Flaky folder chips on load", url: "https://example.invalid/42", labels: [],
      body: "A human filed this: the folder chips are flaky.",
      comments: reviewed ? [{ body: triageComment }, { body: "<!-- factory-review: alice -->" }] : [{ body: triageComment }],
    });

  // BEFORE review: refused. That is the "never before triage/review" half.
  const early = runCli({
    args: ["--promote", "42", "--apply", "--repo", "owner/voicebox"],
    stubGh: ghStubViewing(inbound(false)),
  });
  try {
    assert.equal(early.status, 1, `promotion before review was allowed: ${early.stdout}`);
    assert.match(early.stderr, /carries no review record/);
    assert.equal(early.bdCalls.length, 0, "a pre-review promotion reached bd");
  } finally {
    rmSync(early.box, { recursive: true, force: true });
  }

  // AFTER review: promoted, with the identity, station and severity taken from the triage markers.
  const after = runCli({
    args: ["--promote", "42", "--reviewed-by", "alice", "--apply", "--repo", "owner/voicebox"],
    stubGh: ghStubViewing(inbound(true)),
  });
  try {
    assert.equal(after.status, 0, after.stderr);
    assert.match(after.stdout, new RegExp(`filed: ${fp.slice(0, 16)}`));
    const create = after.bdCalls.find((c) => c.startsWith("create"));
    assert.ok(create, `no bead was created: ${after.bdCalls.join(" | ")}`);
    assert.ok(create.includes(`--external-ref factory:${fp}`), `the bead identity is not the triage fingerprint: ${create}`);
    assert.ok(create.includes("--priority 1"), `severity from the marker did not reach priority: ${create}`);
    assert.ok(create.includes("qa-station"), `the station did not reach the bead: ${create}`);
    assert.ok(create.includes("--title"), "no title");
    // The issue's own words are the bead's subject, sanitised.
    assert.match(create, /Flaky folder chips on load/);
    assert.ok(!/factory\//.test(create), `the bead title kept a publisher prefix: ${create}`);
    // Read-only: nothing was written to the human's issue except the promotion receipt.
    const writes = after.ghCalls.filter((c) => c.startsWith("issue comment"));
    assert.equal(writes.length, 1, `expected exactly the receipt comment: ${writes.join(" | ")}`);
    assert.match(writes[0], /Promoted to bead/);
  } finally {
    rmSync(after.box, { recursive: true, force: true });
  }
});

test("READ-ONLY INBOUND PROMOTION: several findings need --finding, and it refuses to guess", () => {
  const a = "c1".repeat(32);
  const b = "c2".repeat(32);
  const comments = [
    { body: `<!-- factory-triage-comment: ${a} -->\n<!-- factory-station: qa-station -->\n<!-- factory-severity: medium -->\n<!-- factory-state: new -->` },
    { body: `<!-- factory-triage-comment: ${b} -->\n<!-- factory-station: docs-drift -->\n<!-- factory-severity: low -->\n<!-- factory-state: regressed -->` },
  ];
  const untiedIssue = JSON.stringify({
    number: 42, state: "OPEN", title: "Several things at once", url: "https://example.invalid/42", labels: [],
    body: "human words", comments: [...comments, { body: "<!-- factory-review: alice -->" }],
  });
  const tiedIssue = (fingerprint) =>
    JSON.stringify({
      number: 42, state: "OPEN", title: "Several things at once", url: "https://example.invalid/42", labels: [],
      body: "human words",
      comments: [...comments, { body: `<!-- factory-review: alice -->\n<!-- factory-review-fingerprint: ${fingerprint} -->` }],
    });

  const ambiguous = runCli({ args: ["--promote", "42", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(tiedIssue(b)) });
  try {
    assert.equal(ambiguous.status, 1, `an ambiguous promotion was allowed: ${ambiguous.stdout}`);
    assert.match(ambiguous.stderr, /carries 2 findings/);
    assert.match(ambiguous.stderr, /pass --finding <fingerprint> to say which one this bead is for/);
    assert.equal(ambiguous.bdCalls.length, 0, "an ambiguous promotion reached bd");
  } finally {
    rmSync(ambiguous.box, { recursive: true, force: true });
  }

  const chosen = runCli({
    args: ["--promote", "42", "--finding", b.slice(0, 16), "--apply", "--repo", "owner/voicebox"],
    stubGh: ghStubViewing(tiedIssue(b)),
  });
  try {
    assert.equal(chosen.status, 0, chosen.stderr);
    const create = chosen.bdCalls.find((c) => c.startsWith("create"));
    assert.ok(create.includes(`--external-ref factory:${b}`), `--finding picked the wrong identity: ${create}`);
    assert.ok(create.includes("docs-drift"), `--finding did not carry the station through: ${create}`);
  } finally {
    rmSync(chosen.box, { recursive: true, force: true });
  }

  // NEGATIVE CONTROL (coord): a thread with several findings whose verdict is tied to NONE of them
  // authorises no particular identity, so the promotion refuses instead of picking one.
  const untied = runCli({ args: ["--promote", "42", "--finding", b.slice(0, 16), "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(untiedIssue) });
  try {
    assert.equal(untied.status, 1, `an untied verdict authorised a promotion: ${untied.stdout}`);
    assert.match(untied.stderr, /is tied to none of them/);
    assert.match(untied.stderr, /--review <number> --reviewed-by <actor> --finding <fingerprint>/);
    assert.equal(untied.bdCalls.length, 0, "an untied verdict reached bd");
  } finally {
    rmSync(untied.box, { recursive: true, force: true });
  }

  // ...and a verdict tied to a DIFFERENT finding never authorises this one.
  const wrongTie = runCli({ args: ["--promote", "42", "--finding", b.slice(0, 16), "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(tiedIssue(a)) });
  try {
    assert.equal(wrongTie.status, 1, `a verdict for another finding authorised this one: ${wrongTie.stdout}`);
    assert.match(wrongTie.stderr, /but this promotion is for/);
    assert.equal(wrongTie.bdCalls.length, 0, "a mismatched verdict reached bd");
  } finally {
    rmSync(wrongTie.box, { recursive: true, force: true });
  }

  // A prefix matching nothing, or more than one, is refused rather than guessed.
  const noMatch = runCli({ args: ["--promote", "42", "--finding", "ffff", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(tiedIssue(b)) });
  try {
    assert.equal(noMatch.status, 1);
    assert.match(noMatch.stderr, /--finding ffff matches 0 of the findings/);
  } finally {
    rmSync(noMatch.box, { recursive: true, force: true });
  }
});

