test("AN INCOMPLETE report publishes nothing (a killed or timed-out station run)", () => {
  // The declared summary table says how many new/regressed findings the run found. A report whose body
  // stops early declares more than it delivers, and publishing the rows that are present would silently
  // drop the rest — the dropped finding would look like it was never found.
  const complete = fixture("voicebox-qa-station-delta.md");
  // Two shapes of the same failure: the write was cut before the findings started (declares one,
  // delivers none), and the body survived but stops early (declares more than it delivers).
  const headerOnly = complete.slice(0, complete.indexOf("### "));
  const declaredMismatch = complete.replace(/\|\s*\*\*1\*\*\s*\|\s*\*\*0\*\*\s*\|/, "| **3** | **0** |");
  assert.ok(headerOnly.length < complete.length, "the truncation must actually cut the body");

  const shapes = [["cut body", headerOnly], ["declared more than delivered", declaredMismatch]];
  for (const [label, truncated] of shapes) {
    for (const mode of [["--json"], ["--file-issues"]]) {
      const res = runCli({
        args: ["--report", "voicebox-qa-station-delta.md", ...mode, "--repo", "owner/voicebox"],
        reports: { "voicebox-qa-station-delta.md": truncated },
      });
      try {
        assert.equal(res.status, 1, `an incomplete report was accepted (${label}, ${mode}): ${res.stdout}`);
        assert.match(res.stderr, /the report is INCOMPLETE/);
        assert.match(res.stderr, /re-run the station/);
        assert.ok(
          !res.ghCalls.some((c) => c.startsWith("issue create")),
          `an incomplete report published (${label}, ${mode}): ${res.ghCalls.join(" | ")}`,
        );
      } finally {
        rmSync(res.box, { recursive: true, force: true });
      }
    }
  }

  // The same report, complete, still publishes: the check must not refuse a healthy run.
  const ok = runCli({
    args: ["--report", "voicebox-qa-station-delta.md", "--file-issues", "--repo", "owner/voicebox"],
    reports: { "voicebox-qa-station-delta.md": complete },
  });
  try {
    assert.equal(ok.status, 0, ok.stderr);
    assert.ok(ok.ghCalls.some((c) => c.startsWith("issue create")), `a complete report published nothing: ${ok.ghCalls.join(" | ")}`);
  } finally {
    rmSync(ok.box, { recursive: true, force: true });
  }
});

test("A DECLARED state from a triage marker reaches the bead - and a defaulted state is NOT invented (round 10)", () => {
  // miniapps' commenter emits factory-state per finding. The reader carried it on the identity and the
  // bead dropped it, so a promoted regression was indistinguishable from a new finding on the bead a
  // human triages - the one place the difference matters. Driven through the real CLI, because that is
  // the only place "declared" is distinguishable from the `new` default the router uses.
  const fp = "cd".repeat(32);
  const thread = (stateLine) =>
    JSON.stringify({
      number: 21, state: "OPEN", title: "T", url: "https://example.invalid/21", labels: [], body: "human words",
      comments: [
        { body: `<!-- factory-triage-comment: ${fp} -->\n<!-- factory-station: perf-review -->\n<!-- factory-severity: high -->${stateLine}` },
        { body: `<!-- factory-review: alice -->\n<!-- factory-review-fingerprint: ${fp} -->` },
      ],
    });
  const declared = runCli({ args: ["--promote", "21", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread("\n<!-- factory-state: regressed -->")) });
  const undeclared = runCli({ args: ["--promote", "21", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread("")) });
  try {
    const shown = declared.bdCalls.find((c) => c.startsWith("create")) ?? "";
    assert.match(shown, /State: regressed/, `the state marker was read and then dropped: ${shown}`);
    const defaulted = undeclared.bdCalls.find((c) => c.startsWith("create")) ?? "";
    assert.ok(!/State:/.test(defaulted), `a state was invented with no marker: ${defaulted}`);
  } finally {
    for (const res of [declared, undeclared]) rmSync(res.box, { recursive: true, force: true });
  }
});

test("THE OPERATOR can block an inbound promotion: --functionality-change reaches the promotion path (round 10)", () => {
  // Measured gap: promote() parsed no functionality assertion, so an issue whose identity comes from
  // triage comment markers could not be blocked for a functionality change however it was asserted -
  // the flag filed a claimable bead. Blocking must follow the operator's decision, not only a comment
  // flag whose default happens to be "functionality-change".
  const fp = "5d".repeat(32);
  const thread = (station) =>
    JSON.stringify({
      number: 44, state: "OPEN", title: "Inbound", url: "https://example.invalid/44", labels: [], body: "human words",
      comments: [
        { body: `<!-- factory-triage-comment: ${fp} -->\n<!-- factory-station: ${station} -->\n<!-- factory-severity: high -->` },
        { body: `<!-- factory-review: alice -->\n<!-- factory-review-fingerprint: ${fp} -->` },
      ],
    });
  // No flag at all on a non-security station: claimable (nothing asserts a change).
  const bare = runCli({ args: ["--promote", "44", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread("qa-station")) });
  // The operator asserts the station changes functionality: BLOCKED.
  const byStation = runCli({ args: ["--promote", "44", "--apply", "--functionality-change", "qa-station", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread("qa-station")) });
  // The operator asserts the rule id instead: also BLOCKED.
  const byRule = runCli({ args: ["--promote", "44", "--apply", "--functionality-change", "triaged", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread("qa-station")) });
  // An assertion about something else entirely does not block.
  const unrelated = runCli({ args: ["--promote", "44", "--apply", "--functionality-change", "some-other-station", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread("qa-station")) });
  try {
    assert.equal(bare.status, 0, bare.stderr);
    assert.ok(!/BLOCKED/.test(bare.stdout), `an unflagged inbound finding blocked: ${bare.stdout}`);
    for (const [label, res] of [["station", byStation], ["rule", byRule]]) {
      assert.equal(res.status, 0, `${label}: ${res.stderr}`);
      assert.match(res.stdout, /BLOCKED/, `--functionality-change ${label} did not block: ${res.stdout}`);
      // The reason lives on the BLOCKED record: `bd update --status blocked` plus a comment stating why.
      assert.ok(
        res.bdCalls.some((c) => c.startsWith("update") && c.includes("--status blocked")),
        `the bead was not marked blocked: ${res.bdCalls.join(" | ")}`,
      );
      assert.ok(
        res.bdCalls.some((c) => c.startsWith("comment") && /changes functionality/.test(c)),
        `the reason was not recorded: ${res.bdCalls.join(" | ")}`,
      );
      assert.ok(
        !/claimable/.test(res.bdCalls.find((c) => c.startsWith("create")) ?? ""),
        "a blocked bead still claimed to be claimable",
      );
    }
    assert.equal(unrelated.status, 0, unrelated.stderr);
    assert.ok(!/BLOCKED/.test(unrelated.stdout), `an unrelated assertion blocked: ${unrelated.stdout}`);
  } finally {
    for (const res of [bare, byStation, byRule, unrelated]) rmSync(res.box, { recursive: true, force: true });
  }
});

test("ALL MEANS ALL end to end: the default path files low/info issues, and creates no bead (round 11)", () => {
  // Severity preserved on the published issue, dedupe unchanged, and no bead without a reviewed
  // promotion - a purely informational issue need not become work.
  const report = fixture("voicebox-modern-web-delta.md");
  assert.ok(/^### \[(LOW|INFO)\]/m.test(report), "the fixture must carry a low/info finding for this test to mean anything");

  const byDefault = runCli({ args: ["--report", "voicebox-modern-web-delta.md", "--file-issues", "--repo", "owner/voicebox"], reports: { "voicebox-modern-web-delta.md": report } });
  const excluded = runCli({ args: ["--report", "voicebox-modern-web-delta.md", "--file-issues", "--exclude-low", "--repo", "owner/voicebox"], reports: { "voicebox-modern-web-delta.md": report } });
  const redundant = runCli({ args: ["--report", "voicebox-modern-web-delta.md", "--file-issues", "--include-low", "--repo", "owner/voicebox"], reports: { "voicebox-modern-web-delta.md": report } });
  try {
    const created = byDefault.ghCalls.filter((c) => c.startsWith("issue create"));
    assert.ok(created.length > 0, `the default published nothing: ${byDefault.stdout}`);
    assert.ok(!/below the band you asked for/.test(byDefault.stdout), `a low/info finding was skipped by default: ${byDefault.stdout}`);
    // The low finding reaches publication with its severity intact (title names the classifier, the body
    // names the severity) and at priority P3, per the routing rule.
    assert.ok(
      created.some((c) => /factory\/low/.test(c) && /Severity\*\*: low/.test(c)),
      `the low finding's severity did not reach publication: ${created.join(" | ")}`,
    );
    assert.match(byDefault.stdout, /^issues: \d+ published/m, `no receipt: ${byDefault.stdout}`);

    // The opt-out genuinely drops them, and says why.
    assert.match(excluded.stdout, /below the band you asked for with --exclude-low/, excluded.stdout);
    assert.ok(
      excluded.ghCalls.filter((c) => c.startsWith("issue create")).length < created.length,
      `--exclude-low published just as much: ${excluded.ghCalls.join(" | ")}`,
    );

    // The old flag is a no-op, so callers that still pass it are unaffected.
    assert.equal(redundant.status, byDefault.status, redundant.stderr);
    assert.equal(
      redundant.ghCalls.filter((c) => c.startsWith("issue create")).length,
      created.length,
      "--include-low changed the outcome",
    );

    // Nothing here created a bead: a bead still needs an explicit, reviewed promotion.
    for (const res of [byDefault, excluded, redundant]) {
      assert.ok(!res.bdCalls.some((c) => c.startsWith("create")), `a bead was created without a reviewed promotion: ${res.bdCalls.join(" | ")}`);
    }
  } finally {
    for (const res of [byDefault, excluded, redundant]) rmSync(res.box, { recursive: true, force: true });
  }
});

test("THE RECEIPT counts skipped findings, so a mixed run cannot silently drop one (round 11)", () => {
  // A caller that rewrites the report artifact makes a finding's recomputed fingerprint disagree with
  // the prefix it declares, and the publisher then SKIPS it. In a mixed run the receipt used to say only
  // "N published", which hides the skipped finding. Here: one publishable finding plus one whose declared
  // fingerprint was corrupted -> "1 published, 1 skipped", exit 0.
  const base = fixture("voicebox-modern-web-delta.md");
  const other = fixture("voicebox-perf-review-delta.md");
  const otherFinding = other.slice(other.indexOf("### ["));
  const merged = `${base.replace(/\|\s*\*\*1\*\*\s*\|\s*\*\*0\*\*\s*\|/, "| **2** | **0** |")}\n${otherFinding.replace(/\*\*Fingerprint\*\*: `[0-9a-f]{4}/, "**Fingerprint**: `dead")}`;

  const res = runCli({
    args: ["--report", "voicebox-modern-web-delta.md", "--file-issues", "--repo", "owner/voicebox"],
    reports: { "voicebox-modern-web-delta.md": merged },
  });
  try {
    assert.equal(res.status, 0, `the publishable finding should still publish: ${res.stdout}\n${res.stderr}`);
    assert.match(res.stdout, /^issues: 1 published, 0 duplicate, 1 skipped$/m, `the receipt hid the skipped finding: ${res.stdout}`);
    assert.equal(res.ghCalls.filter((c) => c.startsWith("issue create")).length, 1, "exactly one issue should have been created");
  } finally {
    rmSync(res.box, { recursive: true, force: true });
  }
});

test("declaredActionableCount reads the report's own summary table, and says null when there is none", () => {
  assert.equal(declaredActionableCount(fixture("voicebox-qa-station-delta.md")), 1);
  assert.equal(declaredActionableCount("no table here"), null);
  assert.equal(declaredActionableCount(""), null);
  assert.equal(declaredActionableCount(null), null);
  // Bolded and unbolded cells both count, and it reads the FIRST numeric row after the header.
  assert.equal(declaredActionableCount("| New | Regressed |\n|:---:|:---:|\n| 3 | 2 |\n| 9 | 9 |"), 5);
  assert.equal(declaredActionableCount("| New | Regressed |\n| **4** | **1** |"), 5);
});

test("MULTI-VERDICT THREAD: each finding keeps its own reviewer, and each reviewed finding yields one bead (round 9)", () => {
  // Two findings, two verdicts by two different reviewers. The old code resolved the reviewer by
  // scanning the thread globally, so promoting B was attributed to A's reviewer and the CORRECT
  // --reviewed-by was rejected as a mismatch.
  const a = "7a".repeat(32);
  const b = "8b".repeat(32);
  const thread = (extraComments = []) =>
    JSON.stringify({
      number: 12, state: "OPEN", title: "Two findings", url: "https://example.invalid/12", labels: [], body: "human words",
      comments: [
        { body: `<!-- factory-triage-comment: ${a} -->\n<!-- factory-station: qa-station -->\n<!-- factory-severity: high -->` },
        { body: `<!-- factory-triage-comment: ${b} -->\n<!-- factory-station: docs-drift -->\n<!-- factory-severity: low -->` },
        { body: `<!-- factory-review: alice -->\n<!-- factory-review-fingerprint: ${a} -->` },
        { body: `<!-- factory-review: bob -->\n<!-- factory-review-fingerprint: ${b} -->` },
        ...extraComments,
      ],
    });

  // B promoted by bob: accepted, and the bead/receipt name BOB.
  const byBob = runCli({ args: ["--promote", "12", "--finding", b.slice(0, 16), "--reviewed-by", "bob", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread()) });
  // B promoted claiming alice: refused, because alice reviewed A.
  const wrongReviewer = runCli({ args: ["--promote", "12", "--finding", b.slice(0, 16), "--reviewed-by", "alice", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread()) });
  // A promoted by alice: accepted.
  const byAlice = runCli({ args: ["--promote", "12", "--finding", a.slice(0, 16), "--reviewed-by", "alice", "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(thread()) });
  // The issue already carries a promotion record for A: B must STILL be promotable (one bead per
  // reviewed finding), while A itself is refused.
  const afterA = thread([{ body: `<!-- factory-promoted: voicebox-beads-a -->\n<!-- factory-promoted-fingerprint: ${a} -->` }]);
  const secondB = runCli({ args: ["--promote", "12", "--finding", b.slice(0, 16), "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(afterA) });
  const againA = runCli({ args: ["--promote", "12", "--finding", a.slice(0, 16), "--apply", "--repo", "owner/voicebox"], stubGh: ghStubViewing(afterA) });

  try {
    assert.equal(byBob.status, 0, byBob.stderr);
    const bobCreate = byBob.bdCalls.find((c) => c.startsWith("create"));
    assert.match(bobCreate, /by bob/, `the bead was attributed to the wrong reviewer: ${bobCreate}`);
    const bobReceipt = byBob.ghCalls.find((c) => c.startsWith("issue comment"));
    assert.match(bobReceipt, /by bob from 8b8b8b8b8b8b8b8b/, `the receipt named the wrong reviewer: ${bobReceipt}`);
    assert.match(bobReceipt, new RegExp(`factory-promoted-fingerprint: ${b}`), `the receipt did not name the finding: ${bobReceipt}`);

    assert.equal(wrongReviewer.status, 1, `a verdict authorising another finding was accepted: ${wrongReviewer.stdout}`);
    assert.match(wrongReviewer.stderr, /does not match the reviewer recorded/);
    assert.equal(wrongReviewer.bdCalls.length, 0);

    assert.equal(byAlice.status, 0, byAlice.stderr);
    assert.match(byAlice.bdCalls.find((c) => c.startsWith("create")), /by alice/);

    // One bead per reviewed finding: A's record does not block B...
    assert.equal(secondB.status, 0, `an issue-wide record blocked a second reviewed finding: ${secondB.stderr}`);
    assert.ok(secondB.bdCalls.some((c) => c.includes(`--external-ref factory:${b}`)), `B was not promoted: ${secondB.bdCalls.join(" | ")}`);
    // ...and A is still refused, by name and finding.
    assert.equal(againA.status, 1, `the already-promoted finding was promoted twice: ${againA.stdout}`);
    assert.match(againA.stderr, /was already promoted to voicebox-beads-a/);
    assert.equal(againA.bdCalls.length, 0);
  } finally {
    for (const res of [byBob, wrongReviewer, byAlice, secondB, againA]) rmSync(res.box, { recursive: true, force: true });
  }
});
